function transcribe(g){return g.coding.replaceAll('T','U')}
function translate(rna){const aa=['M','A','F','E','Q','W','N','L','D','Y','P','K','V','S','T','R','L','Q','G'];let out='';for(let i=0;i<rna.length-3;i+=3){let c=rna.slice(i,i+3);if(c==='UAA'||c==='UAG'||c==='UGA')break;out+=aa[hashSeed(c)%aa.length]}return out||'M'}
function gc(seq){return seq?((seq.match(/[GC]/g)||[]).length/seq.length*100):0}
function genomeSequence(g){let s='';for(const gene of g.genes){s+=gene.promoter+gene.enhancer+gene.coding.slice(0,Math.floor(gene.coding.length/2))+gene.intron+gene.coding.slice(Math.floor(gene.coding.length/2))}return s+g.noncoding}
