function traitMap(g,env){let map={},stress=environmentStress(env);for(const gene of g.genes){let envFactor=1;if(gene.regulation==='stress-inducible')envFactor=clamp(.24+stress*.95,.18,1);if(gene.regulation==='nutrient-responsive')envFactor=clamp(.22+env.nutrients*.9,.2,1);if(gene.regulation==='developmental')envFactor=.45+Math.sin(g.generation*.11)*.2;map[gene.name]=clamp(gene.activity*envFactor*(1-gene.epi)*(gene.mutation?.8:1),.02,1)}return map}
