function makePresetPlate(key){let preset=PLATE_PRESETS[key]||PLATE_PRESETS.rat,rng=new RNG(hashSeed(`${S.seed}:${key}:preset`)),count=12,plate=[];if(preset.kind==='cell')return{...makePlateState(S.genome,`${S.seed}:${key}`,S.viability,S.atp,count),platePreset:key};for(let i=0;i<count;i++)plate.push({id:`VIRION-${String(i+1).padStart(3,'0')}`,genomeId:S.genome.id,entityKind:'virus',archived:false,sourceLabel:'FREE VIRION',x:12+rng.next()*76,y:14+rng.next()*72,phase:rng.next()*6.28,elementExposures:{}});return{plate,plateSources:{[S.genome.id]:JSON.parse(JSON.stringify(S.genome))},plateSequence:count,selectedCellId:plate[0]?.id||null,platePreset:key}}
